import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BXzK3EA4.js";const r="/assets/06a3d1c5754d444e.CVqbjVtV.png",w=JSON.parse('{"title":"Windows 2012系统卸载某些软件后无法进入系统桌面怎么办","description":"","frontmatter":{"title":"Windows 2012系统卸载某些软件后无法进入系统桌面怎么办"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/windows/windows-2012-desktop-not-loading-after-uninstall.md","filePath":"ops-knowledge-base/operating-system/windows/windows-2012-desktop-not-loading-after-uninstall.md","lastUpdated":1788259091000}'),s={name:"ops-knowledge-base/operating-system/windows/windows-2012-desktop-not-loading-after-uninstall.md"};function l(i,e,p,d,m,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h4 id="一-问题描述" tabindex="-1">一.问题描述 <a class="header-anchor" href="#一-问题描述" aria-label="Permalink to &quot;一.问题描述&quot;">​</a></h4><p>针对Windows 2012操作系统，由于安装应用系统会用到.net framework 3.5，而2012自带的.net framework 4.5版本需要卸载，但是卸载之后可能会遇到黑屏、无法进入系统桌面的问题，只能调出任务管理器。</p><h4 id="二-可能原因" tabindex="-1">二.可能原因 <a class="header-anchor" href="#二-可能原因" aria-label="Permalink to &quot;二.可能原因&quot;">​</a></h4><p>卸载.net framework 4.5后，系统由完整模式Full变为了核心模式Core，没有启用系统桌面。</p><h4 id="三-处理方法" tabindex="-1">三.处理方法 <a class="header-anchor" href="#三-处理方法" aria-label="Permalink to &quot;三.处理方法&quot;">​</a></h4><p>恢复过程就是由核心模式切换到完整模式的过程，步骤如下：</p><ol><li><p>登录服务器。</p></li><li><p>打开任务管理器。</p></li><li><p>选择“文件 &gt; 运行新任务”</p></li></ol><p>系统打开“新建任务”窗口</p><p><img src="'+r+'" alt=""></p><p>4.在“打开”栏，输入“<strong>cmd</strong>”，然后按回车键。</p><p>5.在弹出的命令行窗口执行以下命令，将系统由核心模式切换到完整模式。</p><ul><li><strong>Dism /online /enable-feature /all /featurename:Server-Gui-Mgmt /featurename:Server-Gui-Shell /featurename:ServerCore-FullServer</strong></li></ul><p>6.大概10分钟左右，系统会提示重启，在命令行输入“<strong>Y</strong>”重启系统。</p><p>再次登录系统后就可以正常显示桌面。</p>',14)])])}const _=a(s,[["render",l]]);export{w as __pageData,_ as default};
